CREATE TABLE IF NOT EXISTS voice_fleet_events (id TEXT PRIMARY KEY, namespace TEXT NOT NULL, kind TEXT NOT NULL, payload_json TEXT NOT NULL, direction TEXT NOT NULL CHECK(direction IN ('forward','reverse','mirror')), state TEXT NOT NULL DEFAULT 'HOLD', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS dns_zone_fleet (zone_id TEXT PRIMARY KEY, domain_name TEXT NOT NULL UNIQUE, batch_number INTEGER NOT NULL, cf_status TEXT NOT NULL, gate_mode TEXT NOT NULL DEFAULT 'HOLDING', nameservers_json TEXT, worker_route_id TEXT, alien_seal TEXT, neila_seal TEXT, provisioned_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS mining_risk_ledger (id TEXT PRIMARY KEY, watts REAL NOT NULL CHECK(watts>=0), hours REAL NOT NULL CHECK(hours>=0), usd_per_kwh REAL NOT NULL CHECK(usd_per_kwh>=0), expected_revenue_usd REAL NOT NULL, estimated_cost_usd REAL NOT NULL, expected_margin_usd REAL NOT NULL, decision TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
